from reportlab.lib.pagesizes import A4from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacerfrom reportlab.lib import colorsfrom reportlab.lib.styles import getSampleStyleSheetfrom datetime import datetimeimport osdef make_pdf(results_df, template_meta, explanations, out_path="ComplianceReport.pdf"):    doc = SimpleDocTemplate(out_path, pagesize=A4)    styles = getSampleStyleSheet()    story = []    # Header    title = f"VERA — AI Compliance Co-Pilot"    subtitle = f"Standard: {template_meta.get('standard_id')} v{template_meta.get('version')}"    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M")    story.append(Paragraph(f"<b>{title}</b>", styles["Title"]))    story.append(Paragraph(subtitle, styles["Normal"]))    story.append(Paragraph(f"Generated on: {timestamp}", styles["Normal"]))    story.append(Spacer(1, 12))    # Table (limit to first 12 rows for 1 page)    cols = ["specimen_id", "lot", "status", "rationale"]    data = [cols] + results_df[cols].head(12).values.tolist()    table = Table(data, repeatRows=1)    table.setStyle(TableStyle([        ("BACKGROUND", (0, 0), (-1, 0), colors.lightgrey),        ("TEXTCOLOR", (0, 0), (-1, 0), colors.black),        ("ALIGN", (0, 0), (-1, -1), "LEFT"),        ("GRID", (0, 0), (-1, -1), 0.25, colors.grey),        ("FONTSIZE", (0, 0), (-1, -1), 8),    ]))    story.append(table)    story.append(Spacer(1, 12))    # Explanations    story.append(Paragraph("<b>Explanations</b>", styles["Heading3"]))    for sid, text in explanations.items():        story.append(Paragraph(f"<b>{sid}</b>: {text}", styles["Normal"]))        story.append(Spacer(1, 6))    # Footer metadata (for traceability)    llm_mode = os.environ.get("LLM_MODE", "CLOUD")    llm_model = os.environ.get("OPENAI_MODEL", "gpt-4o-mini")    footer = (        f"VERA — Validation & Explanation for Regulatory Assurance • "        f"Template: {template_meta.get('standard_id')} v{template_meta.get('version')} • "        f"LLM: {llm_model} ({llm_mode}) • Generated: {timestamp}"    )    story.append(Spacer(1, 10))    story.append(Paragraph(footer, styles["Italic"]))    doc.build(story)    return out_path